from pathlib import Path
import re
import json
import html

PROJECT = Path(__file__).resolve().parents[1] / 'site'
OUT = PROJECT / 'design-system'
OUT.mkdir(parents=True, exist_ok=True)
css = (PROJECT / 'feed.css').read_text()
blocks = re.findall(r':root(?:\[data-theme="light"\])?\s*\{(.*?)\n\}', css, re.S)[:2]

def declarations(block):
    clean = re.sub(r'/\*.*?\*/', '', block, flags=re.S)
    return dict(re.findall(r'(--[\w-]+)\s*:\s*([^;]+);', clean))

base, light = map(declarations, blocks)
preview_rules = []
for name in base:
    if name.startswith('--spacing-'):
        preview_rules.append(f'.ds-space-bar[data-token="{name}"] {{ width: var({name}); }}')
    if name.startswith('--color-'):
        preview_rules.append(f'.ds-swatch-color[data-token="{name}"] {{ background: var({name}); }}')
    if name.startswith('--radius-'):
        preview_rules.append(f'.ds-radius > div[data-token="{name}"] {{ border-radius: var({name}); }}')
(OUT / 'previews.css').write_text('\n'.join(preview_rules) + '\n')

def group(name):
    if name.startswith('--spacing-'): return 'Spacing'
    if name.startswith('--type-'): return 'Typography'
    if name.startswith(('--radius-', '--avatar-radius-', '--stroke-')): return 'Shape and stroke'
    if name.startswith('--icon-size-'): return 'Icon sizes'
    if name.startswith('--motion-'): return 'Motion'
    if name.startswith(('--layout-', '--size-', '--avatar-size-')): return 'Layout and size'
    if name.startswith(('--color-', '--trend-up-')): return 'Color'
    return 'Component colors'

tokens = [{'name': n, 'default': v.strip(), 'light': light.get(n, v).strip(), 'group': group(n), 'themeOverride': n in light} for n,v in base.items()]
(OUT / 'tokens.json').write_text(json.dumps({'source': '../feed.css', 'updated': '2026-10-27', 'tokens':tokens}, indent=2) + '\n')

def table(headers, rows):
    return '<div class="ds-table-scroll"><table><thead><tr>'+''.join('<th scope="col">'+h+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'

spacing_notes = ['Small icon and label details', 'Compact gaps and button vertical padding', 'Card text inset and control gaps', 'Panel horizontal padding', 'Standard panel padding and section gaps', 'Larger layout gaps, button horizontal padding and the mobile prediction heading inset', 'Large section spacing']
spacing = ''.join(f'<div class="ds-space-row"><strong>{base[n]}</strong><div><div class="ds-space-bar" data-token="{n}"></div><p>{note}</p><code>{n}</code></div><button class="ds-copy" data-copy="{n}" aria-label="Copy {n}">Copy</button></div>' for n,note in zip([n for n in base if n.startswith('--spacing-')], spacing_notes))
palette_names = [n for n in base if n.startswith('--color-') and n != '--color-white-10']
palette = ''.join(f'<article class="ds-swatch"><div class="ds-swatch-color" data-token="{n}"></div><div><h4>{n.replace("--color-", "").replace("-", " ").capitalize()}</h4><span data-value="{n}">{html.escape(base[n])}</span><button class="ds-copy" data-copy="{n}" aria-label="Copy {n}">Copy</button><code>{n}</code></div></article>' for n in palette_names)

