radius = ''.join(f'<div class="ds-radius"><div data-token="{n}">Aa</div><strong>{base[n]}</strong><code>{n}</code><p>{note}</p></div>' for n,note in [('--radius-x-sm','Primary buttons and panels'),('--radius-sm','Small rounded details'),('--radius-md','Prediction cards and vote buttons'),('--radius-full','Pills and circular shapes')])

