motion = table(['Token','Duration','Used for'], [(f'<code>{n}</code>',base[n],note) for n,note in [('--motion-toast-enter','Toast entrance'),('--motion-toast-exit','Toast dismissal'),('--motion-drawer','Menu drawer'),('--motion-sheet','Article sheet'),('--motion-card-settle','Prediction card spring back'),('--motion-card-fly','Prediction card dismissal'),('--motion-card-flip','Prediction context flip'),('--motion-results-fade','Prediction results entrance'),('--motion-answers-ticker','Answers suggestion ticker loop')]])

